            "solution": "import * as fs from 'node:fs';\nconst lines: string[] = fs.readFileSync(0, 'utf-8').trim().split('\\n').filter((l: string) => l.length > 0);\nconst s: string[] = lines.filter((l: string) => l.split(':')[1] === 'static');\nconst d: string[] = lines.filter((l: string) => l.split(':')[1] === 'dynamic');\nconsole.log([...s, ...d].map((l: string) => l.split(':')[0] + ' (' + l.split(':')[1] + ')').join('\\n'));\n",
